class Solution:
    def removeKdigits(self, num: str, k: int) -> str:
        stack = collections.deque()

        for digit in num:
            while stack and int(stack[-1]) > int(digit) and k > 0:
                stack.pop()
                k -= 1

            stack.append(digit)

        while k > 0:
            stack.pop()
            k -= 1

        while stack and stack[0] == "0":
            stack.popleft()

        return "".join(stack) if stack else "0"
